// ── traits, searchable: every material's unique trait and every people's traits, by name or by what they do ──
let TRAIT_IDX=null;
function traitIdx(){if(TRAIT_IDX)return TRAIT_IDX;const M=new Map();
  MATS.forEach(m=>{if(!m.tr||!m.tr.n||m.tr.rune)return;const k='m|'+m.tr.n;let e=M.get(k);if(!e)M.set(k,e={n:m.tr.n,kind:'mat',t:m.tr.t||'',s:m.tr.s||'',src:[]});e.src.push(m.n)});
  if(typeof PEOPLES!=='undefined'&&PEOPLES.info)Object.entries(PEOPLES.info).forEach(([p,o])=>(o.traits||[]).forEach(([n,t])=>{if(!n)return;const k='p|'+n;let e=M.get(k);if(!e)M.set(k,e={n,kind:'people',t:t||'',src:[]});if(!e.src.includes(p))e.src.push(p)}));
  MONSTERS.forEach(m=>{const tr=m.sb&&m.sb.tr;if(!tr)return;tr.forEach(([n,t])=>{if(!n||/^Signature/.test(n))return;const k='o|'+n;let e=M.get(k);if(!e)M.set(k,e={n,kind:'mon',t:t||'',src:[]});e.src.push(m.n)})});
  if(typeof CLASS_PROG!=='undefined')Object.entries(CLASS_PROG).forEach(([cls,L])=>L.forEach(([lv,n,t])=>{if(!n||/^(Subclass|Ability Score Improvement)$/.test(n))return;const k='c|'+cls+'|'+n;M.set(k,{n,kind:'class',t:t||'',src:[cls],lv,cls,stage:1})}));
  if(typeof STAGES!=='undefined')Object.entries(STAGES).forEach(([cls,L])=>L.forEach(st=>(st.features||[]).forEach(([lv,n,t])=>{if(!n)return;M.set('c|'+cls+'|'+n,{n,kind:'class',t:t||'',src:[st.name],lv,cls,stage:st.stage})})));
  TRAIT_IDX=[...M.values()].sort((a,b)=>a.n.localeCompare(b.n));TRAIT_IDX.forEach(e=>e.hay=lc(e.n+' '+e.t));return TRAIT_IDX}
// rank: the name starts with it, a word in the name starts with it, the name has it, then (4+ letters) what it does mentions it
function traitFind(q,kind){q=lc(q.trim());const L=traitIdx().filter(e=>!kind||e.kind===kind);if(!q)return L;const out=[];
  L.forEach(e=>{const n=lc(e.n);const r=n.startsWith(q)?0:n.includes(' '+q)?1:n.includes(q)?2:q.length>=4&&e.hay.includes(q)?3:-1;if(r>=0)out.push([r,e])});
  return out.sort((a,b)=>a[0]-b[0]||b[1].src.length-a[1].src.length||a[1].n.localeCompare(b[1].n)).map(r=>r[1])}
const TRAIT_KIND={people:['People','acc'],mat:['Material','gold'],mon:['Monster','red'],class:['Class feature','green']};
const traitWhere=e=>e.kind==='mat'?`material trait · ${fmt(e.src.length)} material${e.src.length>1?'s':''}`:e.kind==='class'?`${e.src[0]} feature · level ${e.lv}`:e.kind==='mon'?`monster trait · ${e.src.length>1?fmt(e.src.length)+' monsters':e.src[0]}`:`trait of ${e.src.length>2?e.src.slice(0,2).join(', ')+' +'+(e.src.length-2):e.src.join(' and ')}`;
function traitClass(e){closePalette();openModal();store.set('clsfocus','cl-'+pid(e.cls)+(e.stage>1?'-'+e.stage:''));go('classes');if(TAB==='classes')renderClasses()}
function traitMon(n){const m=MON_IDX.get(lc(n));closePalette();openModal();if(m){if(!SITE&&TAB!=='bestiary'){history.pushState(null,'',hashFor('bestiary'));TAB='bestiary';renderTab()}openItem(m)}}
function traitOpen(e){if(e.kind==='class')return traitClass(e);if(e.kind==='mon'){if(e.src.length===1)return traitMon(e.src[0]);return traitBrowse(e.n,'mon')}if(e.kind==='mat'){closePalette();openModal();go('materials',{f:{tr:e.n}})}else if(e.src.length===1){closePalette();openModal();peoplePop(e.src[0])}else traitBrowse(e.n)}
function traitBrowse(q,kind){closePalette();TB.q=q||'';TB.kind=kind||'';openModal(`<div class="tb"><h3 style="margin:0 0 4px;font-family:var(--serif)">Traits</h3><div class="note" style="margin:0 0 8px">Every people's traits, every material's unique trait, monsters' traits and class features. Search by name or by what it does: try <i>darkvision</i>, <i>fire</i>, <i>advantage</i>. (Spells have their own search on the Spells page.)</div>
  <div class="tb-bar"><input class="sel" id="tb-q" type="search" placeholder="Search traits…" value="${esc(TB.q)}" aria-label="Search traits" autocomplete="off"><span class="chips" id="tb-k">${[['','All'],['people','Peoples'],['mat','Materials'],['mon','Monsters'],['class','Class features']].map(([k,l])=>`<button class="chip${TB.kind===k?' on':''}" data-tbk="${k}">${l}</button>`).join('')}</span></div><div id="tb-out"></div></div>`);
  $('tb-q').oninput=()=>{TB.q=$('tb-q').value;traitList()};$('tb-k').onclick=e=>{const b=e.target.closest('[data-tbk]');if(!b)return;TB.kind=b.dataset.tbk;$('tb-k').querySelectorAll('.chip').forEach(x=>x.classList.toggle('on',x===b));traitList()};traitList();setTimeout(()=>$('tb-q')&&$('tb-q').focus(),10)}
var TB={q:'',kind:''};
function traitList(){const out=$('tb-out');if(!out)return;const L=traitFind(TB.q,TB.kind),q=lc(TB.q.trim());
  out.innerHTML=`<div class="note" style="margin:6px 0">${fmt(L.length)} trait${L.length===1?'':'s'}${L.length>120?', showing the first 120':''}</div>`+(L.length?L.slice(0,120).map((e,i)=>`<div class="tb-row"><div class="tb-h"><b>${q?hl(e.n,q):esc(e.n)}</b> <span class="b ${TRAIT_KIND[e.kind][1]}">${TRAIT_KIND[e.kind][0]}</span>${e.s?` <span class="b ghost">${e.s==='w'?'weapons':'armor'}</span>`:''}</div><div class="tb-t">${esc(e.t)}</div>
    <div class="tb-src">${e.kind==='mat'?`<button class="chip" data-tbi="${i}">${fmt(e.src.length)} material${e.src.length>1?'s':''} with it →</button>`:e.kind==='class'?`<button class="chip" data-tbi="${i}">${esc(e.src[0])} · level ${e.lv} →</button>`:e.kind==='mon'?e.src.slice(0,8).map(n=>`<button class="chip" data-tbm="${esc(n)}">${esc(n)}</button>`).join('')+(e.src.length>8?` <small>+${e.src.length-8} more</small>`:''):e.src.slice(0,8).map(p=>`<button class="chip" data-tbp="${esc(p)}">${esc(p)}</button>`).join('')+(e.src.length>8?` <small>+${e.src.length-8} more</small>`:'')}</div></div>`).join(''):'<div class="empty">No trait matches. Try fewer letters, or search what it does.</div>');
  out.onclick=ev=>{const b=ev.target.closest('[data-tbi],[data-tbp],[data-tbm]');if(!b)return;if(b.dataset.tbm)traitMon(b.dataset.tbm);else if(b.dataset.tbp){openModal();peoplePop(b.dataset.tbp)}else traitOpen(L[+b.dataset.tbi])}}
function paletteSearch(){
  const raw=$('pq').value.trim(),P=palParse(raw.replace(/infinitas/gi,'infinatas')),q=P.q;
  PRES=[];let h=raw?palActions(raw):'';
  {const tm=/^(trait|traits|feature|features):\s*(.*)$/i.exec(raw);if(tm){const kind=/^feature/i.test(tm[1])?'class':'',L=traitFind(tm[2],kind);
    h=`<div class="pal-hint">${kind?'Class features':'Traits'}${tm[2]?` matching “${esc(tm[2])}”`:''} · ${fmt(L.length)}</div>`;L.slice(0,30).forEach(e=>{PRES.push({run:()=>traitOpen(e)});h+=`<button class="pal-i" data-pi="${PRES.length-1}"><span>◆ ${tm[2]?hl(e.n,lc(tm[2].trim())):esc(e.n)}</span><span class="r">${esc(traitWhere(e))}</span></button>`});
    if(L.length>30){PRES.push({run:()=>traitBrowse(tm[2],kind)});h+=`<button class="pal-i" data-pi="${PRES.length-1}"><span>All ${fmt(L.length)} in the trait browser</span><span class="r">browse →</span></button>`}
    if(!L.length)h+=`<div class="empty" style="padding:24px">No ${kind?'class feature':'trait'} matches.</div>`;$('pres').innerHTML=h;PSEL=0;palMark();return}}
  if(P.has){h+=palFiltered(P)}
  else if(!q){
    const rq=store.get('recentq',[]);if(rq.length){h+=`<div class="pal-g">Recent searches</div>`;rq.slice(0,5).forEach(t=>{PRES.push({q:t});h+=`<button class="pal-i" data-pi="${PRES.length-1}"><span>🕘 ${esc(t)}</span><span class="r">search</span></button>`})}
    h+=`<div class="pal-hint">Try <code>monster realm:Hell grade:5</code>, <code>rarity:legendary sword</code>, or <code>roll 2d6+3</code>, <code>trait:fire</code> or <code>feature:rage</code></div>`;
    const pins=pinnedItems().slice(0,8);
    const jump=TABS.filter(t=>t[0]!=='home');
    if(pins.length){h+=`<div class="pal-g">Pinned</div>`;pins.forEach(x=>{PRES.push({x});h+=palRow(x,esc(x.n),PRES.length-1)})}
    const rec=recentItems().filter(x=>!pins.includes(x)).slice(0,6);if(rec.length){h+=`<div class="pal-g">Recently viewed</div>`;rec.forEach(x=>{PRES.push({x});h+=palRow(x,esc(x.n),PRES.length-1)})}
    h+=`<div class="pal-g">Go to</div>`;jump.forEach(([id,l])=>{PRES.push({tab:id});h+=`<button class="pal-i" data-pi="${PRES.length-1}">${l}<span class="r">section</span></button>`});
  } else {
    const best=[];PAL_ORDER.forEach(([t])=>{const arr=TYPES[t].arr;for(const x of arr){const n=lc(x.n),k=lc(x.n.split(' - ')[0]);if(n===q||k===q){best.push(x);if(best.length>=4)break}}});
    const bestSet=new Set(best);
    if(best.length){h+=`<div class="pal-g">Best match</div>`;best.forEach(x=>{PRES.push({x});h+=palRow(x,hl(x.n,q),PRES.length-1)})}
    PAL_ORDER.forEach(([t,label])=>{
      const arr=TYPES[t].arr,hits=[];
      for(let i=0;i<arr.length&&hits.length<60;i++){if(bestSet.has(arr[i]))continue;const n=lc(arr[i].n);const k=n.indexOf(q);if(k>=0)hits.push([k===0?0:n.includes(' '+q)?1:2,arr[i]])}
      if(!hits.length)return;
      hits.sort((a,b)=>a[0]-b[0]||a[1].n.length-b[1].n.length);
      h+=`<div class="pal-g">${label}</div>`;
      hits.slice(0,t==='spell'?4:6).forEach(([,x])=>{PRES.push({x});h+=palRow(x,hl(x.n,q),PRES.length-1)});
    });
    if(typeof STAGES!=='undefined'){const ch=[];Object.entries(STAGES).forEach(([cls,list])=>{if(lc(cls).includes(q))ch.push([cls,1,cls]);list.forEach(x=>{if(lc(x.name).includes(q))ch.push([cls,x.stage,x.name])})});
      if(ch.length){h+=`<div class="pal-g">Classes and class changes</div>`;ch.slice(0,6).forEach(([cls,k,n])=>{PRES.push({tab:'classes',focus:'cl-'+pid(cls)+(k>1?'-'+k:'')});h+=`<button class="pal-i" data-pi="${PRES.length-1}"><span>${hl(n,q)}</span><span class="r">${k>1?'level '+stageStart(k):'class'}</span></button>`})}}
    {const pl=[];Object.entries(REALM_MAPS).forEach(([rn,M])=>M.places.forEach(([g,n])=>{if(lc(n).includes(q))pl.push([rn,g,n])}));if(pl.length){h+=`<div class="pal-g">Places</div>`;pl.slice(0,6).forEach(([rn,g,n])=>{PRES.push({tab:'realms',place:n});h+=`<button class="pal-i" data-pi="${PRES.length-1}"><span>${hl(n,q)}</span><span class="r">${esc(g)} · ${esc(rn)} Realm</span></button>`})}}
    {const tr=q.length>=2?traitFind(q):[];if(tr.length){h+=`<div class="pal-g">Traits <span class="r">${fmt(tr.length)}</span></div>`;tr.slice(0,5).forEach(e=>{PRES.push({run:()=>traitOpen(e)});h+=`<button class="pal-i" data-pi="${PRES.length-1}"><span>◆ ${hl(e.n,q)}</span><span class="r">${esc(traitWhere(e))}</span></button>`});
      if(tr.length>5){PRES.push({run:()=>traitBrowse(q)});h+=`<button class="pal-i" data-pi="${PRES.length-1}"><span>All ${fmt(tr.length)} traits for “${esc(q)}”</span><span class="r">browse →</span></button>`}}}
    // more of the site in the search: Apostle classes, peoples, backgrounds, professions, and each tool on the Tools page
    {const extra=[];const add=(n,r,o)=>{if(lc(n).includes(q))extra.push([n,r,o])};
      GODS.forEach(g=>{const a=apostleOf(g);if(lc(a.name).includes(q)||(q.length>3&&lc(a.title).includes(q)))extra.push([a.name,a.title,{x:g}])});
      if(typeof CW_RACE!=='undefined')CW_RACE.forEach(r=>add(r[0],'people · '+r[5],{run:()=>peopleInfo(r[0])?peoplePop(r[0]):charWizard({race:r[0],step:1})}));
      if(typeof CW_BG!=='undefined')CW_BG.forEach(b=>add(b[0],'background · '+b[3],{run:()=>charWizard({bg:b[0],step:1})}));
      Object.keys(PROFS).forEach(p=>add(p,'profession',{tab:'professions'}));
      [['t-clock','Session clock'],['t-npc','Quick NPC'],['t-trip','Travel and weather'],['t-cond','Conditions'],['t-mine','Mine shaft'],['t-scav','Scavenge a corpse'],['t-dmg','Damage vs. Armor Class'],['t-grade','Material grade'],['t-ref','Refining planner'],['t-enc','Encounter and loot roller'],['t-loot','Treasure'],['t-cur','Currency converter'],['t-travel','Realm Pressure check'],['t-slots','Spell slots'],['t-sb','Stat block creator'],['t-shop','Merchant shop'],['t-backup','Backup']].forEach(([id,n])=>add(n,'tool',{tab:'tools',tool:id}));
      if(extra.length){h+=`<div class="pal-g">Apostle classes, peoples, backgrounds, and tools</div>`;extra.slice(0,8).forEach(([n,r,o])=>{PRES.push(o);h+=`<button class="pal-i" data-pi="${PRES.length-1}"><span>${hl(n,q)}</span><span class="r">${esc(r)}</span></button>`})}}
    if(!SP.length&&META.counts.spells){PRES.push({tab:'spells',setup:{q:$('pq').value.trim()}});h+=`<div class="pal-g">Spells</div><button class="pal-i" data-pi="${PRES.length-1}">Search ${fmt(META.counts.spells)} spells for “${esc($('pq').value.trim())}”<span class="r">Spells page →</span></button>`}
    const tabs=TABS.filter(([,l])=>lc(l).includes(q));
    if(tabs.length){h+=`<div class="pal-g">Sections</div>`;tabs.forEach(([id,l])=>{PRES.push({tab:id});h+=`<button class="pal-i" data-pi="${PRES.length-1}">${l}<span class="r">section</span></button>`})}
    {const ns=noteItems().filter(n=>lc(n.t).includes(q));if(ns.length){h+=`<div class="pal-g">Your notes</div>`;ns.slice(0,5).forEach(n=>{PRES.push({x:n.x});const i=lc(n.t).indexOf(q),snip=n.t.slice(Math.max(0,i-20),i+40);h+=`<button class="pal-i" data-pi="${PRES.length-1}"><span>📝 ${esc(n.x.n)}</span><span class="r">${hl(snip,q)}</span></button>`})}}
    if(PRES.filter(r=>r.x).length<3&&q.length>=4){const dm=palFuzzy(q).filter(x=>!PRES.some(r=>r.x===x));if(dm.length){h+=`<div class="pal-g">Did you mean</div>`;dm.forEach(x=>{PRES.push({x});h+=palRow(x,esc(x.n),PRES.length-1)})}}
    if(!PRES.length)h=`<div class="empty" style="padding:30px">No matches for “${esc(q)}”</div>`;
  }
  $('pres').innerHTML=h;PSEL=0;palMark();
}
function palRow(x,label,i){
  const sub=x._t==='rune'?x.fig.name:x._t==='bp'?x.pr+' · Lv '+x.lv:x._t==='mat'?x.gr||'':x._t==='mon'?x.realm+' '+x.g:x._t==='god'?x.grp:x._t==='spell'?x.sc+' · '+(x.lv?'Lv '+x.lv:'Cantrip'):x._t==='sub'?x.par:x._t==='realm'?'Tier '+x.tier:x.grp||'';
  const col=x._t==='mat'?rcol(x.realm):x._t==='mon'?rcol(x.realm):x._t==='realm'?x.color:x._t==='god'?rcol(x.home):'';
  return `<button class="pal-i" data-pi="${i}">${col?`<span class="sw" style="width:8px;height:8px;border-radius:50%;background:${col};flex-shrink:0"></span>`:''}<span>${label}</span><span class="r">${esc(sub)}</span></button>`;
}
function palMark(){$('pres').querySelectorAll('.pal-i').forEach(b=>b.classList.toggle('sel',+b.dataset.pi===PSEL));const s=$('pres').querySelector('.sel');if(s)s.scrollIntoView({block:'nearest'})}
function palPick(i){const r=PRES[i];if(!r)return;if(r.q){$('pq').value=r.q;paletteSearch();$('pq').focus();return}if(!r.act)palRemember($('pq').value.trim());closePalette();if(r.run){r.run();return}if(r.tool)store.set('tooltab',r.tool);if(r.focus)store.set('clsfocus',r.focus);if(r.place)store.set('placefocus',r.place);if(r.tab){go(r.tab,r.setup);if(r.focus&&TAB==='classes')renderClasses();return}const x=r.x;const tab=TYPES[x._t].tab;if(!SITE&&TAB!==tab){history.pushState(null,'',hashFor(tab));TAB=tab;renderTab()}LIST=VIEWS[TAB]?filtered():[];openItem(x)}
let pTimer;$('pq').addEventListener('input',()=>{clearTimeout(pTimer);pTimer=setTimeout(paletteSearch,60)});
$('pq').addEventListener('keydown',e=>{
  if(e.key==='ArrowDown'){PSEL=Math.min(PRES.length-1,PSEL+1);palMark();e.preventDefault()}
  else if(e.key==='ArrowUp'){PSEL=Math.max(0,PSEL-1);palMark();e.preventDefault()}
  else if(e.key==='Enter'){palPick(PSEL);e.preventDefault()}
});
$('pres').addEventListener('click',e=>{const b=e.target.closest('[data-pi]');if(b)palPick(+b.dataset.pi)});
$('pres').addEventListener('mousemove',e=>{const b=e.target.closest('[data-pi]');if(b&&+b.dataset.pi!==PSEL){PSEL=+b.dataset.pi;palMark()}});

document.addEventListener('keydown',e=>{
  const typing=/INPUT|SELECT|TEXTAREA/.test(document.activeElement.tagName);
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('pbg').classList.contains('open')?closePalette():openPalette();return}
  if(e.key==='Escape'){if($('navpop').classList.contains('open')){closeNav();return}if($('pbg').classList.contains('open'))closePalette();else if($('ai').classList.contains('open')&&!$('mbg').classList.contains('open'))toggleAI(false);else if($('mbg').classList.contains('open'))closeModal();else if($('sb').classList.contains('drawer'))toggleDrawer(false);return}
  if($('mbg').classList.contains('open')&&!typing){if(e.key==='ArrowRight')step(1);if(e.key==='ArrowLeft')step(-1);return}
  if(e.key==='/'&&!typing&&!$('pbg').classList.contains('open')){e.preventDefault();const q=$('q');if(q&&!$('ctrl').hidden)q.focus();else openPalette()}
});

