function applyTheme(t){document.documentElement.dataset.theme=t;$('themeBtn').innerHTML=t==='light'?ICON.moon:ICON.sun;$('themeBtn').title=t==='light'?'Dark theme':'Light theme'}
// Comfort settings: text size (80% to 160%), high contrast, and less motion. Unlike the theme, they follow your account.
const TSCALES=[[.9,'Small'],[1,'Normal'],[1.12,'Large'],[1.25,'Larger'],[1.4,'Largest']];
const lessMotion=()=>document.documentElement.dataset.motion==='reduce'||(store.get('motion','')!=='full'&&matchMedia('(prefers-reduced-motion: reduce)').matches);
function applyComfort(){const d=document.documentElement,z=+store.get('tscale',1);d.style.setProperty('--ts',z>=.8&&z<=1.6?z:1);if(store.get('contrast',false))d.dataset.contrast='high';else delete d.dataset.contrast;if(store.get('motion','')==='reduce')d.dataset.motion='reduce';else delete d.dataset.motion}
function setComfort(k,v){store.set(k,v);applyComfort();if(TAB==='settings')renderSettings()}
// Updates: the site loads its newest pages whenever it is online; this asks the server for this page directly and compares
// build stamps, so "is my copy the newest?" has an answer. GitHub can take up to 10 minutes to hand out a new version.
let UPD_AT=0;
async function newestBuild(){const r=await fetch(location.pathname+'?fresh='+Date.now(),{cache:'no-store'});if(!r.ok)throw new Error(r.status);const m=/,b:"([0-9a-f]+)"/.exec(await r.text());return m?m[1]:null}
async function checkUpdate(quiet){if(!SITE||!SITE.b)return;UPD_AT=Date.now();const out=$('updMsg'),btn=$('updBtn');if(btn){btn.disabled=true;btn.textContent='Checking…'}
  let b=null,err=false;try{b=await newestBuild()}catch(e){err=true}
  const newer=b&&b!==SITE.b;if(newer)$('upd').hidden=false;
  if(btn){btn.disabled=false;btn.textContent='Check for updates'}
  if(out)out.innerHTML=err?'Couldn\'t reach the site. You may be offline; this device still has its saved copy.':newer?'A newer version is out. <button class="btn primary" type="button" onclick="forceUpdate()">Load it now</button>':'You have the newest version.';
  if(!quiet&&!out)toast(err?'Couldn\'t check for updates':newer?'A newer version is ready':'You have the newest version')}
async function forceUpdate(){try{const rg=navigator.serviceWorker&&await navigator.serviceWorker.getRegistration();if(rg)await rg.update()}catch(e){}
  try{const ks=await caches.keys();await Promise.all(ks.filter(k=>k.startsWith('fand-')).map(k=>caches.delete(k)))}catch(e){}location.reload()}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&navigator.onLine&&Date.now()-UPD_AT>15*60e3)checkUpdate(true)});
function toggleTheme(){const t=document.documentElement.dataset.theme==='light'?'dark':'light';store.set('theme',t);applyTheme(t)}
applyTheme(store.get('theme',matchMedia&&matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'));applyComfort();

