// Home's first section: the pages a player or a DM reaches for most, or (before they choose) the question.
const ROLE_HOME={player:['sheet','party','dice','spells','journal','rules','chargen','classes','craft','guide'],dm:['prep','encounter','combat','hidden','bestiary','hooks','npcs','towers','shop','forge']};
// the shortcuts can be chosen (owner's request, 2026-11-05): a list per role, kept on this device and in the account
const homeQuick=r=>{const s=store.get('homeQuick.'+r,null),ok=id=>TABS.some(t=>t[0]===id)&&id!=='home'&&!(r==='player'&&DM_ONLY.includes(id));return (Array.isArray(s)&&s.length?s:ROLE_HOME[r]).filter(ok)};
let HQ_EDIT=false;
function hqToggle(id,on){const r=role(),L=homeQuick(r).filter(x=>x!==id);if(on)L.push(id);store.set('homeQuick.'+r,L.length?L:null);renderTab()}
function hqReset(){store.set('homeQuick.'+role(),null);renderTab()}
// the Choose shortcuts card stretches over whatever is left of the last row, so the grid never ends with a gap
function hqFill(){const g=document.querySelector('.qgrid.hq'),m=g&&g.querySelector('.hq-more');if(!m)return;m.style.gridColumn='';
  const cols=getComputedStyle(g).gridTemplateColumns.split(' ').filter(Boolean).length||1,cards=g.querySelectorAll('.home-qlink:not(.hq-more)').length,left=cols-(cards%cols);if(left>1)m.style.gridColumn='span '+left}
window.addEventListener('resize',()=>{clearTimeout(hqFill.t);hqFill.t=setTimeout(hqFill,120)});
function homeRoleHTML(){const r=role();
  if(!r)return `<section class="sec"><div class="callout" style="display:flex;gap:12px;align-items:center;flex-wrap:wrap"><div style="flex:1;min-width:220px"><b>How do you use FAND?</b><br><span class="note" style="margin:0">FAND puts the pages you use most first: your character for players, the table tools for DMs. Change it any time in Settings.</span></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" type="button" onclick="setRole('player')">I'm a player</button><button class="btn primary" type="button" onclick="setRole('dm')">I'm the DM</button><button class="btn" type="button" onclick="setRole('both')">Both</button></div></div></section>`;
  if(r==='both')return '';
  return `<section class="sec"><div class="sec-h"><h3>${r==='dm'?'Your table':'Your character'}</h3><p>${ROLES[r]} view · <a href="${pageUrl('settings')}#set-play" data-go="settings">change</a></p></div><div class="qgrid hq">${homeQuick(r).map(id=>{const t=TABS.find(x=>x[0]===id);return t?`<a class="home-qlink" href="${pageUrl(id)}" data-go="${id}"><b>${esc(t[1])}</b><small>${esc(NAV_BLURB[id]||'')}</small></a>`:''}).join('')}<button type="button" class="home-qlink hq-more" aria-expanded="${HQ_EDIT}" onclick="HQ_EDIT=!HQ_EDIT;renderTab()"><b>${HQ_EDIT?'✓ Done choosing':'＋ Choose shortcuts'}</b><small>${HQ_EDIT?'Close the list':'Pick which pages show here'}</small></button></div>${HQ_EDIT?hqEditHTML(r):''}</section>${(setTimeout(hqFill,0),'')}`}
function hqEditHTML(r){const on=new Set(homeQuick(r));
  return `<div class="panel hq-edit" style="margin-top:10px"><div style="display:flex;gap:10px;align-items:baseline;flex-wrap:wrap;margin-bottom:6px"><b>Shortcuts on Home</b><span class="note" style="margin:0">${on.size} chosen · tick the pages you reach for most</span><button type="button" class="btn" style="margin-left:auto" onclick="hqReset()">Reset to the ${r==='dm'?'DM':'player'} set</button></div>
    ${navGroups().map(([g,ids])=>{const L=ids.filter(id=>id!=='home'&&!(r==='player'&&DM_ONLY.includes(id))&&TABS.some(t=>t[0]===id));return L.length?`<div style="margin:8px 0 2px;font-size:.72rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)">${esc(g)}</div><div class="chips">${L.map(id=>`<label class="chip hq-pick${on.has(id)?' on':''}"><input type="checkbox" ${on.has(id)?'checked':''} onchange="hqToggle('${id}',this.checked)"> ${esc((TABS.find(t=>t[0]===id)||[])[1]||id)}</label>`).join('')}</div>`:''}).join('')}</div>`}
// Customise Home: move sections up and down, or hide the ones you don't use
let HOME_EDIT=false;
const homeL=()=>Object.assign({order:[],hidden:[]},store.get('homelayout',{}));
function homeLayout(S){const H=homeL(),ord=S.slice().sort((a,b)=>{const ia=H.order.indexOf(a[0]),ib=H.order.indexOf(b[0]);return (ia<0?99+S.indexOf(a):ia)-(ib<0?99+S.indexOf(b):ib)});
  const body=ord.map(([k,l,f],i)=>{const hid=H.hidden.includes(k);if(hid&&!HOME_EDIT)return '';let h='';try{h=f()||''}catch(e){h=''}
    return HOME_EDIT?`<div class="hsec${hid?' off':''}" data-hk="${k}"><div class="hsec-bar"><b>${esc(l)}</b><button type="button" class="btn" data-hmv="-1" ${i?'':'disabled'} aria-label="Move ${esc(l)} up">↑</button><button type="button" class="btn" data-hmv="1" ${i<ord.length-1?'':'disabled'} aria-label="Move ${esc(l)} down">↓</button><button type="button" class="btn${hid?' primary':''}" data-hhide>${hid?'Show':'Hide'}</button></div>${h||'<div class="note" style="padding:6px 0">(nothing to show here yet)</div>'}</div>`:h}).join('');
  return (HOME_EDIT?`<div class="callout hedit-top"><b>Customise Home</b><span class="note" style="margin:0;flex:1">Move sections with ↑ ↓, hide what you don't use. Saved in your account.</span><button type="button" class="btn" data-hreset>Reset</button><button type="button" class="btn primary" data-hdone>Done</button></div>`:'')+body+(HOME_EDIT?'':`<div style="text-align:center;margin:18px 0 6px"><button type="button" class="btn" data-hedit>✎ Customise Home</button></div>`)}
// the Customise Home bar is sticky: in Chrome, pressing one of its buttons after scrolling focuses it and jumps the page back
// to the bar's place before the mouse comes up, so the click never lands. Not taking focus on mousedown keeps the click.
function homeBind(){const C=$('content');C.querySelectorAll('.hedit-top button').forEach(b=>b.onmousedown=e=>e.preventDefault());C.querySelectorAll('[data-hedit],[data-hdone],[data-hreset],[data-hmv],[data-hhide]').forEach(b=>b.onclick=()=>{const H=homeL(),k=(b.closest('[data-hk]')||{}).dataset;
  if(b.dataset.hedit!=null)HOME_EDIT=true;else if(b.dataset.hdone!=null)HOME_EDIT=false;else if(b.dataset.hreset!=null){store.set('homelayout',{});HOME_EDIT=false;toast('Home reset')}
  else{const keys=[...C.querySelectorAll('[data-hk]')].map(e=>e.dataset.hk);if(b.dataset.hmv){const i=keys.indexOf(k.hk),j=i+ +b.dataset.hmv;[keys[i],keys[j]]=[keys[j],keys[i]];H.order=keys}else{H.hidden=H.hidden.includes(k.hk)?H.hidden.filter(x=>x!==k.hk):H.hidden.concat(k.hk);H.order=keys}store.set('homelayout',H)}
  const y=C.scrollTop;renderHome();C.scrollTop=y})}
// ── saved searches: a list page's search and filters, kept with your account and shown on Home ──
function searchLabel(tab){const V=VIEWS[tab],s=st(tab),p=[];if(s.q)p.push('“'+s.q+'”');if(s.side)p.push(s.side.replace('|',' › '));
  V.filters.forEach(f=>{const v=s.f[f.id];if(!v)return;if(f.chip)p.push(f.chip(v));else{const o=(V._opts[f.id]||f.opts()).find(x=>x[0]===v);p.push(o?o[1]:v)}});V.toggles.forEach(t=>{if(s.tg[t.id])p.push(t.label.replace(/<[^>]+>/g,''))});return p.join(', ')}
function saveSearch(){const V=VIEWS[TAB];if(!V)return;const s=st(TAB),L=store.get('savedq',[]),pg=((TABS.find(x=>x[0]===TAB)||[])[1]||V.title),def=searchLabel(TAB)||pg;
  const name=prompt('Name this search (it goes on your Home page):',def.length>60?def.slice(0,57)+'…':def);if(name===null)return;
  const setup={q:s.q||'',f:Object.assign({},s.f),tg:Object.assign({},s.tg),side:s.side||''};if(s.sort)setup.sort=s.sort;
  const key=JSON.stringify([TAB,setup]);if(L.some(x=>JSON.stringify([x.tab,x.s])===key)){toast('That search is already saved');return}
  L.unshift({id:'sq'+Date.now().toString(36),tab:TAB,name:(name.trim()||def).slice(0,80),s:setup,at:Date.now()});store.set('savedq',L.slice(0,24));toast('Saved: it\'s on your Home page')}
function savedOpen(id){const x=store.get('savedq',[]).find(z=>z.id===id);if(x)go(x.tab,JSON.parse(JSON.stringify(x.s)))}
function savedDrop(id){const L=store.get('savedq',[]),x=L.find(z=>z.id===id);store.set('savedq',L.filter(z=>z.id!==id));renderHome();if(x)undoToast('Removed '+x.name,()=>{store.set('savedq',L);renderHome()})}
function savedHomeHTML(){const L=store.get('savedq',[]);if(!L.length)return '';
  return `<section class="sec"><div class="sec-h"><h3>Saved searches</h3><p>${L.length} saved · open a list page, search or filter it, then ☆ Save search</p></div><div class="sq-grid">${L.map(x=>`<div class="sq-card"><button class="sq-open" type="button" onclick="savedOpen('${x.id}')">${pgSym(x.tab,'statsym')}<span><b>${esc(x.name)}</b><small>${esc(((TABS.find(t=>t[0]===x.tab)||[])[1]||x.tab).replace(/<[^>]+>/g,''))}</small></span></button><button class="sq-x" type="button" aria-label="Remove ${esc(x.name)}" title="Remove" onclick="savedDrop('${x.id}')">✕</button></div>`).join('')}</div></section>`}
// ── This week (Home): what is waiting for this person's characters, gathered in one place ──
function weekHTML(){const me=typeof CL!=='undefined'&&CL.user&&CL.user.id,mine=PARTY.filter(c=>clMine(c)),ids=new Set(mine.map(c=>c.id)),rows=[],add=(ic,t,act,lbl,hot)=>rows.push({ic,t,act,lbl,hot});
  if(!mine.length)return '';
  const loot=(LT.list||[]).filter(r=>r.status==='open'&&mine.some(c=>c.camp===r.campaign_id)&&!(r.claims||[]).some(x=>ids.has(x.char)));if(loot.length)add('💰',`${loot.length} loot item${loot.length>1?'s':''} to claim: ${loot.slice(0,3).map(r=>r.n).join(', ')}${loot.length>3?'…':''}`,"go('shop')",'Claim',1);
  (SW.list||[]).filter(r=>r.status==='offered'&&r.to_user===me).forEach(r=>add('⇄',`${swName(r,'from')} offers ${swName(r,'to')} ${swList(r.give)} for ${swList(r.want)}`,"go('shop')",'Answer',1));
  (TR.list||[]).filter(r=>r.status==='countered'&&r.requester===me).forEach(r=>add('🪙',`Your DM offers ${gp(+r.price)} each to ${r.kind} ${r.qty>1?r.qty+' × ':''}${r.item}`,"go('shop')",'Answer',1));
  const wait=(TR.list||[]).filter(r=>['open','agreed'].includes(r.status)&&r.requester===me).length+(SW.list||[]).filter(r=>r.status==='offered'&&r.from_user===me).length;if(wait)add('⏳',`${wait} request${wait>1?'s':''} or offer${wait>1?'s':''} waiting on others`,"go('shop')",'See');
  const d=calDay();calDT().filter(x=>!x.done&&ids.has(x.cid)).forEach(x=>add('📅',`${x.who}: ${x.label}, ${Math.max(0,x.end-d)} day${x.end-d===1?'':'s'} to go (ends day ${x.end})`,'calOpen()','Calendar'));
  calEvents().concat(questsDue()).filter(e=>e.day>=d&&e.day<=d+14).sort((a,b)=>a.day-b.day).slice(0,4).forEach(e=>add(e.quest?'📜':'🗓',`Day ${e.day}${e.day===d?' (today)':''}: ${e.t}`,'calOpen()','Calendar'));
  const un=store.get('inbox',[]).filter(x=>!x.read).length;if(un)add('🔔',`${un} unread in your inbox`,'inboxToggle(true)','Open');
  return `<section class="sec wk"><div class="sec-h"><h3>This week</h3><p>${rows.length?'What is waiting for '+esc(mine.length===1?mine[0].name||'your character':'your characters'):'Nothing waiting'}</p></div>
    ${rows.length?`<div class="wk-list">${rows.map(x=>`<div class="wk-row${x.hot?' hot':''}"><span class="wk-ic" aria-hidden="true">${x.ic}</span><span class="wk-t">${esc(x.t)}</span><button class="btn${x.hot?' primary':''}" type="button" onclick="${x.act}">${esc(x.lbl)}</button></div>`).join('')}</div>`:`<div class="note">No loot to claim, no offers, nothing coming up. Downtime, trades and calendar events show up here.</div>`}</section>`}
